import{_ as t,a,b as r,c as s,d as n,e,f as i,g as l,h as g}from"./chunks/sound-wave.UVZ-guYw.js";import{_ as p,o as u,c as m,a2 as d}from"./chunks/framework.Bzj1XTnB.js";const x=JSON.parse('{"title":"आवाज़","description":"मुफ़्त लाइब्रेरी से साउंड इफ़ेक्ट, म्यूज़िक जिंगल और आवाज़ें जोड़ें, आवाज़ बनाएँ, अपनी आवाज़ रिकॉर्ड करें और आवाज़ को फ़्रेम से मिलाएँ।","frontmatter":{"lang":"hi","slug":"sound","order":8,"title":"आवाज़","description":"मुफ़्त लाइब्रेरी से साउंड इफ़ेक्ट, म्यूज़िक जिंगल और आवाज़ें जोड़ें, आवाज़ बनाएँ, अपनी आवाज़ रिकॉर्ड करें और आवाज़ को फ़्रेम से मिलाएँ।"},"headers":[],"relativePath":"hi/sound.md","filePath":"hi/sound.md"}'),c={name:"hi/sound.md"};function h(_,o,q,b,f,k){return u(),m("div",null,[...o[0]||(o[0]=[d('<h1 id="आवाज़" tabindex="-1">आवाज़ <a class="header-anchor" href="#आवाज़" aria-label="Permalink to &quot;आवाज़&quot;">​</a></h1><p>ऑडियो एडिटर खोलने के लिए नीचे की पट्टी में <strong>Audio</strong> टैप करें।</p><p><img src="'+t+'" alt="ऑडियो एडिटर"></p><ul><li>ऊपर का <strong>प्रीव्यू</strong> नीली प्लेहेड वाला फ़्रेम दिखाता है।</li><li><strong>🔊</strong> काम करते समय सारी आवाज़ बंद या चालू करता है।</li><li><strong>⏮ ▶ ⏭</strong> — यहाँ से चलाएँ, या शुरुआत या आख़िर पर जाएँ।</li><li>दाईं ओर के चार बटन: <strong>Sound FX</strong> (साउंड लाइब्रेरी खोलता है), <strong>Voice maker</strong>, <strong>Record audio</strong> और <strong>Import audio</strong> (फ़ोन से म्यूज़िक, या किसी वीडियो फ़ाइल की आवाज़)।</li><li><strong>6 ट्रैक</strong> हैं, ताकि कई आवाज़ें एक साथ बज सकें। हर ट्रैक को म्यूट या लॉक कर सकते हैं।</li><li>सबसे नीचे आपके फ़्रेम चलते हैं, ताकि आवाज़ ठीक सही ड्रॉइंग से मिला सकें।</li></ul><p>नई आवाज़ें प्लेहेड पर रखी जाती हैं। क्लिप हिलाने के लिए <strong>खींचें</strong>, छोटा करने के लिए उसके सिरे खींचें, और सटीक टाइमिंग के लिए <strong>पिंच</strong> करके ज़ूम करें।</p><h2 id="क्लिप-के-काम" tabindex="-1">क्लिप के काम <a class="header-anchor" href="#क्लिप-के-काम" aria-label="Permalink to &quot;क्लिप के काम&quot;">​</a></h2><p>किसी क्लिप पर <strong>लॉन्ग-प्रेस</strong> करें — <strong>Rename</strong>, <strong>Duplicate</strong>, <strong>Split at playhead</strong>, <strong>Volume</strong> और <strong>Delete</strong>।</p><p><img src="'+a+'" alt="क्लिप के काम"></p><h2 id="साउंड-लाइब्रेरी" tabindex="-1">साउंड लाइब्रेरी <a class="header-anchor" href="#साउंड-लाइब्रेरी" aria-label="Permalink to &quot;साउंड लाइब्रेरी&quot;">​</a></h2><p><strong>169 आवाज़ें, सब मुफ़्त</strong>, अलग-अलग पैक में: Toonik basics, Fight, Cartoon &amp; game, Footsteps &amp; moves, Home &amp; objects, Sci-fi &amp; machines, Clicks &amp; alerts, Music jingles और Voices (एक अनाउंसर जो &quot;3, 2, 1, Go!&quot;, &quot;You win&quot;, &quot;Game over&quot;… बोलता है)।</p><p><img src="'+r+'" alt="साउंड लाइब्रेरी"></p><p>कोई पैक खोलें, सुनने के लिए <strong>▶</strong> और टाइमलाइन पर डालने के लिए <strong>+ ADD</strong> टैप करें। हर आवाज़ के साथ छोटा सा विवरण है कि वह कैसी सुनाई देती है।</p><p><img src="'+s+'" alt="एक साउंड पैक"></p><h3 id="खोजना" tabindex="-1">खोजना <a class="header-anchor" href="#खोजना" aria-label="Permalink to &quot;खोजना&quot;">​</a></h3><p>जो सुनना है, अपने शब्दों में लिखें — एक शब्द या पूरा वाक्य:</p><ul><li>&quot;door&quot; · &quot;someone slamming the door shut&quot; · &quot;footsteps on snow&quot; · &quot;laser gun&quot; · &quot;a happy win tune&quot;</li></ul><p>अंग्रेज़ी अक्षरों में हिंदी शब्द भी चलते हैं:</p><ul><li>&quot;bada dhamaka&quot; · &quot;darwaza band&quot; · &quot;jeet&quot; · &quot;paisa&quot;</li></ul><p>सबसे सही नतीजे सबसे ऊपर आते हैं।</p><p><img src="'+n+'" alt="वाक्य से खोजना"></p><p><img src="'+e+'" alt="हिंग्लिश में खोजना"></p><p>साउंड पैक Kenney (kenney.nl) के हैं और पब्लिक डोमेन में हैं, इसलिए इन्हें अपनी किसी भी रचना में इस्तेमाल कर सकते हैं — उन वीडियो में भी जिनसे आप कमाई करते हैं।</p><h2 id="voice-maker" tabindex="-1">Voice maker <a class="header-anchor" href="#voice-maker" aria-label="Permalink to &quot;Voice maker&quot;">​</a></h2><p>एक लाइन लिखें, <strong>Voice</strong> (Normal, Kid, Deep, Squeaky, Sleepy) और <strong>Language</strong> (English या हिन्दी) चुनें, सुनने के लिए <strong>Preview</strong> और जोड़ने के लिए <strong>Add to timeline</strong> टैप करें।</p><p><img src="'+i+'" alt="वॉइस मेकर"></p><h2 id="अपनी-आवाज़-रिकॉर्ड-करें" tabindex="-1">अपनी आवाज़ रिकॉर्ड करें <a class="header-anchor" href="#अपनी-आवाज़-रिकॉर्ड-करें" aria-label="Permalink to &quot;अपनी आवाज़ रिकॉर्ड करें&quot;">​</a></h2><p><strong>Record audio</strong> टैप करें, पहली बार माइक्रोफ़ोन की अनुमति दें, फिर रिकॉर्ड करने के लिए <strong>बटन दबाकर रखें</strong> और रोकने के लिए छोड़ दें। ड्रॉइंग के साथ-साथ बोलने के लिए <strong>Play animation while recording</strong> चालू करें। रिकॉर्डिंग मौजूदा फ़्रेम से शुरू होती है।</p><p><img src="'+l+'" alt="ऑडियो रिकॉर्ड करना"></p><h2 id="बीट-पर-एनिमेट-करें" tabindex="-1">बीट पर एनिमेट करें <a class="header-anchor" href="#बीट-पर-एनिमेट-करें" aria-label="Permalink to &quot;बीट पर एनिमेट करें&quot;">​</a></h2><p><strong>App settings → Sound</strong> में <strong>Sound while animating</strong> चालू करें (जब तक आप चालू न करें, यह बंद रहता है)। फिर:</p><ul><li>फ़्रेम पर जाते ही या फ़्रेम की पट्टी खींचते समय <strong>उस फ़्रेम की आवाज़ बजती है</strong>, ताकि ठीक-ठीक सुनाई दे कि कोई शब्द या ठक कहाँ पड़ता है।</li><li>जिस फ़्रेम पर बीट पड़ती है — ढोल की थाप, ताली, कोई सुर — उसके ऊपर एक <strong>गुलाबी नोट</strong> दिखता है। अपने मुख्य पोज़ वहीं रखें।</li><li>एनिमेशन <strong>चलाते समय आवाज़ की लहर स्क्रीन पर रहती है</strong>: गुज़रती हुई लहर (बजा हुआ हिस्सा गुलाबी), हर बीट पर एक बिंदु, और बीच का प्लेहेड जो बीट गुज़रते ही चमकता है। ऊपर की पट्टी में हीरे के बगल वाला लहर बटन इसे छिपाता या दिखाता है।</li></ul><p><img src="'+g+'" alt="चलाते समय आवाज़ की लहर"></p>',32)])])}const V=p(c,[["render",h]]);export{x as __pageData,V as default};
